INSERT INTO public.project_question_actions (project_id, question_id, action_id)
VALUES ('p19','19000000-2026-4000-8000-000000002111','7d557b96-fd9d-4624-8cae-c42163ad6daf')
ON CONFLICT (question_id, action_id) DO NOTHING;

DO $$
DECLARE
  unlinked integer;
BEGIN
  SELECT count(*) INTO unlinked
  FROM public.project_actions a
  WHERE a.project_id = 'p19'
    AND a.deleted_at IS NULL
    AND a.review_state = 'accepted'
    AND left(a.id::text, 33) = '19000000-2026-4000-8000-000000002'
    AND NOT EXISTS (
      SELECT 1 FROM public.project_question_actions qa WHERE qa.action_id = a.id
    );

  IF unlinked <> 0 THEN
    RAISE EXCEPTION 'ZMP cockpit still has % reviewed current actions without a direct question link', unlinked;
  END IF;
END $$;

COMMIT;
